+fn arc_vertices(pts: &[Point2], segs: &[Seg]) -> Vec<(Point2, Point2, f64)> {
+    let mut out = Vec::new();
+    let mut at = 0usize;
+    for s in segs {
+        match s {
+            Seg::Line(qs) => at += qs.len(),
+            Seg::Arc { center, to, .. } => {
+                let end = (at + 1..pts.len()).find(|&k| pts[k] == *to).expect("an arc ends on an input vertex");
